/**
 * @file API client for the management panel backend.
 * Provides typed methods for all REST endpoints.
 */

import axios from 'axios';
import type { AxiosInstance } from 'axios';
import type { DockerApp, SetupStatus, UserProfile, AppConfig, Customer, ServerPreset, ServerMetric, AccessLog, ConfigVersion, MaintenanceWindow, BackupJob, BackupStatusEntry, BackupArtifactsResponse, AlertConfig, AlertHistoryEntry, HealthCheck, ScheduledTask, GitDeployment, Database, BillingInfo, Transaction, BillingRates, CostEstimate, Modpack, ModpackInstallation, ServerCloneRequest, ServerRoleAssignment, ServerSnapshot, AutopilotRecommendation, ServerWorkspace, ServerBillingLedger } from './types.ts';
import type { CreatureView } from '../components/FleetPet';

const API_URL = (import.meta as any).env?.VITE_API_URL || 'http://localhost:3001';

export type { APIClient };

/**
 * API client that wraps axios and provides typed methods for all endpoints.
 * Manages JWT token lifecycle and request configuration.
 */
class APIClient {
  private api: AxiosInstance;
  private token: string | null = null;

  constructor() {
    this.api = axios.create({
      baseURL: API_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });
    // Pick up a persisted session synchronously so the first requests fired
    // by deep-linked routes already carry auth. Without this, pages mounted
    // before the setup-status roundtrip fetch without a token (401) and
    // bounce back to /dashboard. Guarded for non-browser runtimes (tests).
    try {
      const stored =
        typeof localStorage !== 'undefined' ? localStorage.getItem('sb_access_token') : null;
      if (stored) this.setToken(stored);
    } catch {
      // storage unavailable (private mode, tests) �?" remain unauthenticated
    }
  }

  setToken(token: string) {
    this.token = token;
    this.api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  }

  clearToken() {
    this.token = null;
    delete this.api.defaults.headers.common['Authorization'];
  }

  // Setup endpoints
