    key: 'living_fleet',
    description: 'Living-fleet creature UX and orchestrator mood engine.',
    value_type: 'boolean',
    default_value: false,
    fail_mode: 'closed',
    status: 'active',
    expires_at: null,
    rules: {},
  },
];
